SELECT CASE WHEN z.chg=0 OR NOT ((IFNULL(z.hs_c,'')<>IFNULL(z.hs_p,'') OR IFNULL(z.hr_c,'')<>IFNULL(z.hr_p,'')) OR (IFNULL(z.ps_c,'')<>IFNULL(z.ps_p,''))) THEN 'Susunan majelis yang bersidang sama dengan sidang yang lalu;' ELSE CONCAT('Susunan majelis sidang sebelumnya mengalami perubahan karena ',CONCAT_WS(' dan ',NULLIF(IF(NOT (IFNULL(z.hs_c,'')<>IFNULL(z.hs_p,'') OR IFNULL(z.hr_c,'')<>IFNULL(z.hr_p,'')),'',IF(NOT (IFNULL(z.hs_c,'')<>IFNULL(z.hs_p,'')),'terjadi perubahan susunan jabatan Majelis Hakim',IF(IFNULL(z.h_out,'')<>'' AND IFNULL(z.h_in,'')<>'',CONCAT('Hakim bernama ',IF((LENGTH(z.h_out)-LENGTH(REPLACE(z.h_out,'|','')))=0,z.h_out,IF((LENGTH(z.h_out)-LENGTH(REPLACE(z.h_out,'|','')))=1,REPLACE(z.h_out,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.h_out,'|',(LENGTH(z.h_out)-LENGTH(REPLACE(z.h_out,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.h_out,'|',-1)))),' yang sebelumnya bertugas',IF(IFNULL(z.h_ket,'')='','',IF(LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket)))) REGEXP '^(sedang|telah|sudah)[ ]',CONCAT(' ',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket)))),IF(LENGTH(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))))<=40 AND LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket)))) NOT REGEXP '^(hakim|ketua|anggota|panitera|salah|perkara|majelis)',CONCAT(' sedang ',CONCAT(LOWER(LEFT(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))),1)),SUBSTRING(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))),2))),CONCAT(' (',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))),')')))),' digantikan oleh ',IF((LENGTH(z.h_in)-LENGTH(REPLACE(z.h_in,'|','')))=0,z.h_in,IF((LENGTH(z.h_in)-LENGTH(REPLACE(z.h_in,'|','')))=1,REPLACE(z.h_in,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.h_in,'|',(LENGTH(z.h_in)-LENGTH(REPLACE(z.h_in,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.h_in,'|',-1))))),IF(IFNULL(z.h_in,'')<>'',CONCAT('Hakim bernama ',IF((LENGTH(z.h_in)-LENGTH(REPLACE(z.h_in,'|','')))=0,z.h_in,IF((LENGTH(z.h_in)-LENGTH(REPLACE(z.h_in,'|','')))=1,REPLACE(z.h_in,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.h_in,'|',(LENGTH(z.h_in)-LENGTH(REPLACE(z.h_in,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.h_in,'|',-1)))),' ditunjuk menjadi bagian dari susunan majelis'),CONCAT('Hakim bernama ',IF((LENGTH(z.h_out)-LENGTH(REPLACE(z.h_out,'|','')))=0,z.h_out,IF((LENGTH(z.h_out)-LENGTH(REPLACE(z.h_out,'|','')))=1,REPLACE(z.h_out,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.h_out,'|',(LENGTH(z.h_out)-LENGTH(REPLACE(z.h_out,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.h_out,'|',-1)))),' tidak lagi bertugas',IF(IFNULL(z.h_ket,'')='','',IF(LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket)))) REGEXP '^(sedang|telah|sudah)[ ]',CONCAT(' ',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket)))),IF(LENGTH(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))))<=40 AND LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket)))) NOT REGEXP '^(hakim|ketua|anggota|panitera|salah|perkara|majelis)',CONCAT(' sedang ',CONCAT(LOWER(LEFT(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))),1)),SUBSTRING(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))),2))),CONCAT(' (',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.h_ket))),')'))))))))),''),NULLIF(IF(NOT (IFNULL(z.ps_c,'')<>IFNULL(z.ps_p,'')),'',IF(IFNULL(z.p_out,'')<>'' AND IFNULL(z.p_in,'')<>'',CONCAT(z.pn,' bernama ',IF((LENGTH(z.p_out)-LENGTH(REPLACE(z.p_out,'|','')))=0,z.p_out,IF((LENGTH(z.p_out)-LENGTH(REPLACE(z.p_out,'|','')))=1,REPLACE(z.p_out,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.p_out,'|',(LENGTH(z.p_out)-LENGTH(REPLACE(z.p_out,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.p_out,'|',-1)))),' yang sebelumnya bertugas',IF(IFNULL(z.p_ket,'')='','',IF(LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket)))) REGEXP '^(sedang|telah|sudah)[ ]',CONCAT(' ',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket)))),IF(LENGTH(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))))<=40 AND LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket)))) NOT REGEXP '^(hakim|ketua|anggota|panitera|salah|perkara|majelis)',CONCAT(' sedang ',CONCAT(LOWER(LEFT(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))),1)),SUBSTRING(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))),2))),CONCAT(' (',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))),')')))),' digantikan oleh ',IF((LENGTH(z.p_in)-LENGTH(REPLACE(z.p_in,'|','')))=0,z.p_in,IF((LENGTH(z.p_in)-LENGTH(REPLACE(z.p_in,'|','')))=1,REPLACE(z.p_in,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.p_in,'|',(LENGTH(z.p_in)-LENGTH(REPLACE(z.p_in,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.p_in,'|',-1))))),IF(IFNULL(z.p_in,'')<>'',CONCAT(z.pn,' bernama ',IF((LENGTH(z.p_in)-LENGTH(REPLACE(z.p_in,'|','')))=0,z.p_in,IF((LENGTH(z.p_in)-LENGTH(REPLACE(z.p_in,'|','')))=1,REPLACE(z.p_in,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.p_in,'|',(LENGTH(z.p_in)-LENGTH(REPLACE(z.p_in,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.p_in,'|',-1)))),' ditunjuk mendampingi sidang'),CONCAT(z.pn,' bernama ',IF((LENGTH(z.p_out)-LENGTH(REPLACE(z.p_out,'|','')))=0,z.p_out,IF((LENGTH(z.p_out)-LENGTH(REPLACE(z.p_out,'|','')))=1,REPLACE(z.p_out,'|',' dan '),CONCAT(REPLACE(SUBSTRING_INDEX(z.p_out,'|',(LENGTH(z.p_out)-LENGTH(REPLACE(z.p_out,'|','')))),'|',', '),' dan ',SUBSTRING_INDEX(z.p_out,'|',-1)))),' tidak lagi bertugas',IF(IFNULL(z.p_ket,'')='','',IF(LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket)))) REGEXP '^(sedang|telah|sudah)[ ]',CONCAT(' ',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket)))),IF(LENGTH(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))))<=40 AND LOWER(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket)))) NOT REGEXP '^(hakim|ketua|anggota|panitera|salah|perkara|majelis)',CONCAT(' sedang ',CONCAT(LOWER(LEFT(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))),1)),SUBSTRING(TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))),2))),CONCAT(' (',TRIM(TRAILING '.' FROM TRIM(TRAILING ';' FROM TRIM(z.p_ket))),')')))))))),'')),', berdasarkan ',IF((IFNULL(z.hs_c,'')<>IFNULL(z.hs_p,'') OR IFNULL(z.hr_c,'')<>IFNULL(z.hr_p,'')) AND (IFNULL(z.ps_c,'')<>IFNULL(z.ps_p,'')) AND z.hc=z.pc AND IFNULL(z.h_nomor,'')='' AND IFNULL(z.p_nomor,'')='',CONCAT('Penetapan ',IF((z.t_n IS NOT NULL),'Hakim Tunggal (PHT)','Majelis Hakim (PMH)'),' dan Penunjukan Panitera Pengganti (PPP) pengganti tanggal ',TRIM(LEADING '0' FROM CONVERT(convert_tanggal_indonesia(z.hc) USING utf8))),CONCAT_WS(' dan ',NULLIF(IF(NOT (IFNULL(z.hs_c,'')<>IFNULL(z.hs_p,'') OR IFNULL(z.hr_c,'')<>IFNULL(z.hr_p,'')),'',CONCAT('Penetapan ',IF((z.t_n IS NOT NULL),'Hakim Tunggal (PHT)','Majelis Hakim (PMH)'),' pengganti',IF(IFNULL(z.h_nomor,'')<>'',CONCAT(' Nomor ',z.h_nomor),''),' tanggal ',TRIM(LEADING '0' FROM CONVERT(convert_tanggal_indonesia(z.hc) USING utf8)))),''),NULLIF(IF(NOT (IFNULL(z.ps_c,'')<>IFNULL(z.ps_p,'')),'',CONCAT('Penunjukan Panitera Pengganti (PPP) pengganti',IF(IFNULL(z.p_nomor,'')<>'',CONCAT(' Nomor ',z.p_nomor),''),' tanggal ',TRIM(LEADING '0' FROM CONVERT(convert_tanggal_indonesia(z.pc) USING utf8)))),''))),', sehingga susunan majelis bersidang menjadi sebagai berikut:',IF((z.t_n IS NOT NULL),CONCAT('<br>-<li><strong>',z.t_n,'</strong> sebagai Hakim Tunggal; dan dibantu',CONCAT('<br><li><strong>',IFNULL(z.pp_n,'-'),'</strong> sebagai ',z.pn,';')),CONCAT('<br>1.<li><strong>',IFNULL(z.k_n,'-'),'</strong> sebagai Ketua Majelis;',IF(z.a1_n IS NULL,'',CONCAT('<br>2.<li><strong>',z.a1_n,'</strong> sebagai Hakim Anggota;')),IF(z.a2_n IS NULL,'',CONCAT('<br>3.<li><strong>',z.a2_n,'</strong> sebagai Hakim Anggota;')),' dan dibantu',CONCAT('<br><li><strong>',IFNULL(z.pp_n,'-'),'</strong> sebagai ',z.pn,';')))) END AS data
FROM (
SELECT e.*,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba1.nama_gelar,a1.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) ORDER BY LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba1.nama_gelar,a1.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) SEPARATOR '|') FROM perkara_hakim_pn a1 LEFT JOIN hakim_pn ba1 ON ba1.id=a1.hakim_id WHERE a1.perkara_id=#perkara_id# AND a1.tanggal_penetapan=e.hc AND (a1.tanggal_tidak_aktif IS NULL OR a1.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a1.tanggal_penetapan))),NULL) AS hs_c,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba2.nama_gelar,a2.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) ORDER BY LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba2.nama_gelar,a2.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) SEPARATOR '|') FROM perkara_hakim_pn a2 LEFT JOIN hakim_pn ba2 ON ba2.id=a2.hakim_id WHERE a2.perkara_id=#perkara_id# AND a2.tanggal_penetapan=e.hp AND (a2.tanggal_tidak_aktif IS NULL OR a2.tanggal_tidak_aktif>e.prv OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a2.tanggal_penetapan))),NULL) AS hs_p,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT CONCAT(CAST(IFNULL(a3.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba3.nama_gelar,a3.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-',''))) ORDER BY CONCAT(CAST(IFNULL(a3.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba3.nama_gelar,a3.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-',''))) SEPARATOR '|') FROM perkara_hakim_pn a3 LEFT JOIN hakim_pn ba3 ON ba3.id=a3.hakim_id WHERE a3.perkara_id=#perkara_id# AND a3.tanggal_penetapan=e.hc AND (a3.tanggal_tidak_aktif IS NULL OR a3.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a3.tanggal_penetapan))),NULL) AS hr_c,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT CONCAT(CAST(IFNULL(a4.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba4.nama_gelar,a4.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-',''))) ORDER BY CONCAT(CAST(IFNULL(a4.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba4.nama_gelar,a4.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-',''))) SEPARATOR '|') FROM perkara_hakim_pn a4 LEFT JOIN hakim_pn ba4 ON ba4.id=a4.hakim_id WHERE a4.perkara_id=#perkara_id# AND a4.tanggal_penetapan=e.hp AND (a4.tanggal_tidak_aktif IS NULL OR a4.tanggal_tidak_aktif>e.prv OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a4.tanggal_penetapan))),NULL) AS hr_p,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a5.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) ORDER BY LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a5.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) SEPARATOR '|') FROM perkara_panitera_pn a5 WHERE a5.perkara_id=#perkara_id# AND a5.tanggal_penetapan=e.pc AND (a5.tanggal_tidak_aktif IS NULL OR a5.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a5.tanggal_penetapan))),NULL) AS ps_c,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a6.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) ORDER BY LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a6.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) SEPARATOR '|') FROM perkara_panitera_pn a6 WHERE a6.perkara_id=#perkara_id# AND a6.tanggal_penetapan=e.pp AND (a6.tanggal_tidak_aktif IS NULL OR a6.tanggal_tidak_aktif>e.prv OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a6.tanggal_penetapan))),NULL) AS ps_p,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT CONVERT(IFNULL(ba7.nama_gelar,a7.hakim_nama) USING utf8) ORDER BY a7.jabatan_hakim_id, a7.urutan, a7.id SEPARATOR '|') FROM perkara_hakim_pn a7 LEFT JOIN hakim_pn ba7 ON ba7.id=a7.hakim_id WHERE a7.perkara_id=#perkara_id# AND a7.tanggal_penetapan=e.hp AND (a7.tanggal_tidak_aktif IS NULL OR a7.tanggal_tidak_aktif>e.prv OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a7.tanggal_penetapan)) AND LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba7.nama_gelar,a7.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) NOT IN (SELECT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba8.nama_gelar,a8.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) FROM perkara_hakim_pn a8 LEFT JOIN hakim_pn ba8 ON ba8.id=a8.hakim_id WHERE a8.perkara_id=#perkara_id# AND a8.tanggal_penetapan=e.hc AND (a8.tanggal_tidak_aktif IS NULL OR a8.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a8.tanggal_penetapan)))),NULL) AS h_out,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT CONVERT(IFNULL(ba9.nama_gelar,a9.hakim_nama) USING utf8) ORDER BY a9.jabatan_hakim_id, a9.urutan, a9.id SEPARATOR '|') FROM perkara_hakim_pn a9 LEFT JOIN hakim_pn ba9 ON ba9.id=a9.hakim_id WHERE a9.perkara_id=#perkara_id# AND a9.tanggal_penetapan=e.hc AND (a9.tanggal_tidak_aktif IS NULL OR a9.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a9.tanggal_penetapan)) AND LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba9.nama_gelar,a9.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) NOT IN (SELECT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(IFNULL(ba10.nama_gelar,a10.hakim_nama) USING utf8)),' ',''),',',''),'.',''),'-','')) FROM perkara_hakim_pn a10 LEFT JOIN hakim_pn ba10 ON ba10.id=a10.hakim_id WHERE a10.perkara_id=#perkara_id# AND a10.tanggal_penetapan=e.hp AND (a10.tanggal_tidak_aktif IS NULL OR a10.tanggal_tidak_aktif>e.prv OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a10.tanggal_penetapan)))),NULL) AS h_in,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT CONVERT(a11.panitera_nama USING utf8) ORDER BY a11.urutan, a11.id SEPARATOR '|') FROM perkara_panitera_pn a11 WHERE a11.perkara_id=#perkara_id# AND a11.tanggal_penetapan=e.pp AND (a11.tanggal_tidak_aktif IS NULL OR a11.tanggal_tidak_aktif>e.prv OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a11.tanggal_penetapan)) AND LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a11.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) NOT IN (SELECT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a12.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) FROM perkara_panitera_pn a12 WHERE a12.perkara_id=#perkara_id# AND a12.tanggal_penetapan=e.pc AND (a12.tanggal_tidak_aktif IS NULL OR a12.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a12.tanggal_penetapan)))),NULL) AS p_out,
  IF(e.chg=1,(SELECT GROUP_CONCAT(DISTINCT CONVERT(a13.panitera_nama USING utf8) ORDER BY a13.urutan, a13.id SEPARATOR '|') FROM perkara_panitera_pn a13 WHERE a13.perkara_id=#perkara_id# AND a13.tanggal_penetapan=e.pc AND (a13.tanggal_tidak_aktif IS NULL OR a13.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a13.tanggal_penetapan)) AND LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a13.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) NOT IN (SELECT LOWER(REPLACE(REPLACE(REPLACE(REPLACE(TRIM(CONVERT(a14.panitera_nama USING utf8)),' ',''),',',''),'.',''),'-','')) FROM perkara_panitera_pn a14 WHERE a14.perkara_id=#perkara_id# AND a14.tanggal_penetapan=e.pp AND (a14.tanggal_tidak_aktif IS NULL OR a14.tanggal_tidak_aktif>e.prv OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>a14.tanggal_penetapan)))),NULL) AS p_in,
  IF(e.chg=1,IFNULL((SELECT GROUP_CONCAT(DISTINCT CONVERT(TRIM(k.keterangan) USING utf8) ORDER BY k.urutan SEPARATOR '; ') FROM perkara_hakim_pn k WHERE k.perkara_id=#perkara_id# AND k.tanggal_penetapan=e.hc AND k.keterangan IS NOT NULL AND TRIM(k.keterangan)<>'' AND TRIM(k.keterangan) NOT REGEXP '^(c[0-9]|[abc]|pmh|pht|phs|isbat terpadu|perkara sidkel|perkara sidang keliling|sidang keliling.*|sidkel.*)$'),(SELECT GROUP_CONCAT(DISTINCT CONVERT(TRIM(k.keterangan) USING utf8) ORDER BY k.urutan SEPARATOR '; ') FROM perkara_hakim_pn k WHERE k.perkara_id=#perkara_id# AND k.tanggal_penetapan=e.hp AND k.keterangan IS NOT NULL AND TRIM(k.keterangan)<>'' AND TRIM(k.keterangan) NOT REGEXP '^(c[0-9]|[abc]|pmh|pht|phs|isbat terpadu|perkara sidkel|perkara sidang keliling|sidang keliling.*|sidkel.*)$')),NULL) AS h_ket,
  IF(e.chg=1,IFNULL((SELECT GROUP_CONCAT(DISTINCT CONVERT(TRIM(k.keterangan) USING utf8) ORDER BY k.urutan SEPARATOR '; ') FROM perkara_panitera_pn k WHERE k.perkara_id=#perkara_id# AND k.tanggal_penetapan=e.pc AND k.keterangan IS NOT NULL AND TRIM(k.keterangan)<>'' AND TRIM(k.keterangan) NOT REGEXP '^(c[0-9]|[abc]|pmh|pht|phs|isbat terpadu|perkara sidkel|perkara sidang keliling|sidang keliling.*|sidkel.*)$'),(SELECT GROUP_CONCAT(DISTINCT CONVERT(TRIM(k.keterangan) USING utf8) ORDER BY k.urutan SEPARATOR '; ') FROM perkara_panitera_pn k WHERE k.perkara_id=#perkara_id# AND k.tanggal_penetapan=e.pp AND k.keterangan IS NOT NULL AND TRIM(k.keterangan)<>'' AND TRIM(k.keterangan) NOT REGEXP '^(c[0-9]|[abc]|pmh|pht|phs|isbat terpadu|perkara sidkel|perkara sidang keliling|sidang keliling.*|sidkel.*)$')),NULL) AS p_ket,
  IF(e.chg=1,(SELECT CONVERT(MAX(NULLIF(NULLIF(TRIM(k.nomor_sk_penetapan),''),'NULL')) USING utf8) FROM perkara_hakim_pn k WHERE k.perkara_id=#perkara_id# AND k.tanggal_penetapan=e.hc),NULL) AS h_nomor,
  IF(e.chg=1,(SELECT CONVERT(MAX(NULLIF(NULLIF(TRIM(k.nomor_sk_penetapan),''),'NULL')) USING utf8) FROM perkara_panitera_pn k WHERE k.perkara_id=#perkara_id# AND k.tanggal_penetapan=e.pc),NULL) AS p_nomor,
  IF(e.chg=1,(SELECT CONVERT(IFNULL(bb1.nama_gelar,b1.hakim_nama) USING utf8) FROM perkara_hakim_pn b1 LEFT JOIN hakim_pn bb1 ON bb1.id=b1.hakim_id WHERE b1.perkara_id=#perkara_id# AND b1.tanggal_penetapan=e.hc AND (b1.tanggal_tidak_aktif IS NULL OR b1.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>b1.tanggal_penetapan)) AND b1.jabatan_hakim_id=1 ORDER BY b1.urutan, b1.id LIMIT 1),NULL) AS k_n,
  IF(e.chg=1,(SELECT CONVERT(IFNULL(bb2.nama_gelar,b2.hakim_nama) USING utf8) FROM perkara_hakim_pn b2 LEFT JOIN hakim_pn bb2 ON bb2.id=b2.hakim_id WHERE b2.perkara_id=#perkara_id# AND b2.tanggal_penetapan=e.hc AND (b2.tanggal_tidak_aktif IS NULL OR b2.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>b2.tanggal_penetapan)) AND b2.jabatan_hakim_id=2 ORDER BY b2.urutan, b2.id LIMIT 1),NULL) AS a1_n,
  IF(e.chg=1,(SELECT CONVERT(IFNULL(bb3.nama_gelar,b3.hakim_nama) USING utf8) FROM perkara_hakim_pn b3 LEFT JOIN hakim_pn bb3 ON bb3.id=b3.hakim_id WHERE b3.perkara_id=#perkara_id# AND b3.tanggal_penetapan=e.hc AND (b3.tanggal_tidak_aktif IS NULL OR b3.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>b3.tanggal_penetapan)) AND b3.jabatan_hakim_id=2 ORDER BY b3.urutan, b3.id LIMIT 1,1),NULL) AS a2_n,
  IF(e.chg=1,(SELECT CONVERT(IFNULL(bb4.nama_gelar,b4.hakim_nama) USING utf8) FROM perkara_hakim_pn b4 LEFT JOIN hakim_pn bb4 ON bb4.id=b4.hakim_id WHERE b4.perkara_id=#perkara_id# AND b4.tanggal_penetapan=e.hc AND (b4.tanggal_tidak_aktif IS NULL OR b4.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>b4.tanggal_penetapan)) AND b4.jabatan_hakim_id=3 ORDER BY b4.urutan, b4.id LIMIT 1),NULL) AS t_n,
  IF(e.chg=1,(SELECT GROUP_CONCAT(CONVERT(b5.panitera_nama USING utf8) ORDER BY b5.urutan, b5.id SEPARATOR ' dan ') FROM perkara_panitera_pn b5 WHERE b5.perkara_id=#perkara_id# AND b5.tanggal_penetapan=e.pc AND (b5.tanggal_tidak_aktif IS NULL OR b5.tanggal_tidak_aktif>e.cur OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>b5.tanggal_penetapan))),NULL) AS pp_n
FROM (SELECT e1.*, IF(e1.ada=1 AND (e1.hc<>e1.hp OR e1.pc<>e1.pp) AND (IFNULL(e1.hi_c,'')<>IFNULL(e1.hi_p,'') OR IFNULL(e1.pi_c,'')<>IFNULL(e1.pi_p,'')),1,0) AS chg
FROM (SELECT d.*,
  IF(d.ada=1 AND (d.hc<>d.hp OR d.pc<>d.pp),(SELECT GROUP_CONCAT(CONCAT(CAST(IFNULL(c1.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',CAST(IFNULL(c1.hakim_id,0) AS CHAR CHARACTER SET utf8)) ORDER BY CONCAT(CAST(IFNULL(c1.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',CAST(IFNULL(c1.hakim_id,0) AS CHAR CHARACTER SET utf8)) SEPARATOR '|') FROM perkara_hakim_pn c1 WHERE c1.perkara_id=#perkara_id# AND c1.tanggal_penetapan=d.hc AND (c1.tanggal_tidak_aktif IS NULL OR c1.tanggal_tidak_aktif>d.cur OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>c1.tanggal_penetapan))),NULL) AS hi_c,
  IF(d.ada=1 AND (d.hc<>d.hp OR d.pc<>d.pp),(SELECT GROUP_CONCAT(CONCAT(CAST(IFNULL(c2.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',CAST(IFNULL(c2.hakim_id,0) AS CHAR CHARACTER SET utf8)) ORDER BY CONCAT(CAST(IFNULL(c2.jabatan_hakim_id,0) AS CHAR CHARACTER SET utf8),':',CAST(IFNULL(c2.hakim_id,0) AS CHAR CHARACTER SET utf8)) SEPARATOR '|') FROM perkara_hakim_pn c2 WHERE c2.perkara_id=#perkara_id# AND c2.tanggal_penetapan=d.hp AND (c2.tanggal_tidak_aktif IS NULL OR c2.tanggal_tidak_aktif>d.prv OR NOT EXISTS (SELECT 1 FROM perkara_hakim_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>c2.tanggal_penetapan))),NULL) AS hi_p,
  IF(d.ada=1 AND (d.hc<>d.hp OR d.pc<>d.pp),(SELECT GROUP_CONCAT(CAST(IFNULL(c3.panitera_id,0) AS CHAR CHARACTER SET utf8) ORDER BY CAST(IFNULL(c3.panitera_id,0) AS CHAR CHARACTER SET utf8) SEPARATOR '|') FROM perkara_panitera_pn c3 WHERE c3.perkara_id=#perkara_id# AND c3.tanggal_penetapan=d.pc AND (c3.tanggal_tidak_aktif IS NULL OR c3.tanggal_tidak_aktif>d.cur OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>c3.tanggal_penetapan))),NULL) AS pi_c,
  IF(d.ada=1 AND (d.hc<>d.hp OR d.pc<>d.pp),(SELECT GROUP_CONCAT(CAST(IFNULL(c4.panitera_id,0) AS CHAR CHARACTER SET utf8) ORDER BY CAST(IFNULL(c4.panitera_id,0) AS CHAR CHARACTER SET utf8) SEPARATOR '|') FROM perkara_panitera_pn c4 WHERE c4.perkara_id=#perkara_id# AND c4.tanggal_penetapan=d.pp AND (c4.tanggal_tidak_aktif IS NULL OR c4.tanggal_tidak_aktif>d.prv OR NOT EXISTS (SELECT 1 FROM perkara_panitera_pn zz WHERE zz.perkara_id=#perkara_id# AND zz.tanggal_penetapan>c4.tanggal_penetapan))),NULL) AS pi_p
FROM (SELECT IFNULL((SELECT MAX(h0.tanggal_penetapan) FROM perkara_hakim_pn h0 WHERE h0.perkara_id=#perkara_id# AND h0.tanggal_penetapan<=par.cur),(SELECT MIN(h0.tanggal_penetapan) FROM perkara_hakim_pn h0 WHERE h0.perkara_id=#perkara_id#)) AS hc,IFNULL((SELECT MAX(h0.tanggal_penetapan) FROM perkara_hakim_pn h0 WHERE h0.perkara_id=#perkara_id# AND h0.tanggal_penetapan<=par.prv),(SELECT MIN(h0.tanggal_penetapan) FROM perkara_hakim_pn h0 WHERE h0.perkara_id=#perkara_id#)) AS hp,IFNULL((SELECT MAX(h0.tanggal_penetapan) FROM perkara_panitera_pn h0 WHERE h0.perkara_id=#perkara_id# AND h0.tanggal_penetapan<=par.cur),(SELECT MIN(h0.tanggal_penetapan) FROM perkara_panitera_pn h0 WHERE h0.perkara_id=#perkara_id#)) AS pc,IFNULL((SELECT MAX(h0.tanggal_penetapan) FROM perkara_panitera_pn h0 WHERE h0.perkara_id=#perkara_id# AND h0.tanggal_penetapan<=par.prv),(SELECT MIN(h0.tanggal_penetapan) FROM perkara_panitera_pn h0 WHERE h0.perkara_id=#perkara_id#)) AS pp,IF(STR_TO_DATE(par.prv,'%Y-%m-%d') IS NULL,0,1) AS ada,par.cur AS cur,par.prv AS prv,par.pn AS pn FROM (SELECT "#0033#" AS cur,"#6091#" AS prv,"#6034#" AS pn) par) d) e1) e
) z
